function DeleteLinkExample() {
  const confirm = useConfirmationModal();

  return (
    <Button
      variant="destructive"
      onClick={async () => {
        const ok = await confirm({
          type: "delete",
          message: "Do you want to delete this payment link?",
          description: "The action can't be undone.",
        });
        if (ok) {
          save();
        }
      }}
    >
      Delete link
    </Button>
  );
}

render(<DeleteLinkExample />);

